using PA.Tickets.Domain.Tickets;
using PA.Tickets.Application.Foundations;
namespace PA.Tickets.Application.Tickets;
public sealed record CreateTicketCommand(TicketType Type,string Subject,string? Description,long RequesterUserId,long CreatorUserId,long? RequestTypeId=null,IReadOnlyCollection<PA.Tickets.Application.Foundations.TicketFieldValue>? FieldValues=null,string? IdempotencyKey=null,long? ServiceId=null,long? CategoryId=null,long? SubCategoryId=null,long? PriorityId=null);
public sealed record TicketView(long Id,string Number,TicketType Type,TicketStatus Status,string Subject,long? PriorityId,long? CurrentDepartmentId,long? CurrentTeamId,long? CurrentAssignee,IReadOnlyCollection<WorkItemView> WorkItems,long? ServiceId=null,long? CategoryId=null,long? SubCategoryId=null,long? RequestTypeId=null,int? RequestTypeVersion=null);
public sealed record WorkItemView(long Id,string Number,string PublicId,string Status,long? AssignedToUserId,string? WaitingFor,string? WaitingComment,string? WaitingEvidenceReference,DateTimeOffset? WaitingExpectedDate,int WaitingMinutes);
public sealed record TicketSearchCriteria(string? Number,TicketStatus? Status,TicketType? Type,long? PriorityId,long? ServiceId,long? CategoryId,long? RequestTypeId,long? ClientId,long? DepartmentId,long? TeamId,long? AssigneeId,DateTimeOffset? CreatedFrom,DateTimeOffset? CreatedTo,int Page=1,int PageSize=25);
public sealed record TicketSearchPage(IReadOnlyCollection<TicketView> Items,int Page,int PageSize,int TotalCount);
public interface ITicketLifecycleService { Task<TicketView> CreateAsync(CreateTicketCommand command,CancellationToken ct); Task<TicketView> GetAsync(long id,long actor,CancellationToken ct); Task<TicketSearchPage> SearchAsync(TicketSearchCriteria criteria,long actor,CancellationToken ct); Task<TicketView> ClassifyAsync(long id,long serviceId,long categoryId,long requestTypeId,long priorityId,long actor,CancellationToken ct); Task<TicketView> RouteAsync(long id,long? departmentId,long? teamId,long actor,CancellationToken ct); Task<TicketView> RequestApprovalAsync(long id,long approver,long actor,CancellationToken ct); Task<TicketView> ApproveAsync(long id,long approver,CancellationToken ct); Task<TicketView> ExecuteAsync(long id,long workItemId,long executor,long actor,CancellationToken ct); Task<TicketView> ReassignAsync(long id,long workItemId,long assignee,long actor,string? reason,CancellationToken ct); Task<TicketView> WaitAsync(long id,long workItemId,WaitingRequest request,long actor,CancellationToken ct); Task<TicketView> ResumeAsync(long id,long workItemId,long actor,CancellationToken ct); Task<TicketView> AddEvidenceAsync(long id,long actor,CancellationToken ct); Task<TicketView> CompleteWorkAsync(long id,long workItemId,long actor,CancellationToken ct); Task<TicketView> ResolveAsync(long id,long actor,CancellationToken ct); Task<TicketView> ReopenAsync(long id,string reason,long actor,CancellationToken ct); Task<TicketView> CancelAsync(long id,string reason,long actor,CancellationToken ct); Task<TicketView> CloseAsync(long id,long actor,CancellationToken ct); Task<TicketView> TransitionSpecializedStatusAsync(long id,TicketStatus status,long actor,string? reason,CancellationToken ct); Task<TicketRelationship> AddRelationshipAsync(long id,long relatedId,string relationType,string? description,long actor,CancellationToken ct); }
public interface ITicketRepository { Task<Ticket?> GetAsync(long id,CancellationToken ct); Task AddAsync(Ticket ticket,CancellationToken ct); Task AddAsync(Ticket ticket,IReadOnlyCollection<PA.Tickets.Application.Foundations.TicketFieldValue> values,long actor,CancellationToken ct)=>AddAsync(ticket,ct); Task AddAsync(Ticket ticket,IReadOnlyCollection<PA.Tickets.Application.Foundations.TicketFieldValue> values,long actor,string? idempotencyKey,CancellationToken ct)=>AddAsync(ticket,values,actor,ct); Task SaveAsync(Ticket ticket,CancellationToken ct); Task AddRelationshipAsync(TicketRelationship relationship,CancellationToken ct); Task<TicketSearchPage> SearchAsync(TicketSearchCriteria criteria,CancellationToken ct); }
public interface ITicketIdentityGenerator { Task<(long Id,string Number)> NextAsync(TicketType type,CancellationToken ct); Task<long> NextWorkItemIdAsync(CancellationToken ct); }
public interface ITicketAccessAuthorizer
{
    Task EnsureCanMutateAsync(long actorUserId,Ticket ticket,CancellationToken ct);
    Task EnsureCanAccessAsync(long actorUserId,Ticket ticket,CancellationToken ct);
    Task EnsureCanSearchAsync(long actorUserId,CancellationToken ct);
    Task<TicketSearchCriteria> ScopeSearchAsync(long actorUserId,TicketSearchCriteria criteria,CancellationToken ct) => Task.FromResult(criteria);
    Task EnsureCanAssignAsync(long actorUserId,AuthorizationResource ticketResource,long? departmentId,long? teamId,long? assigneeUserId,CancellationToken ct) => Task.CompletedTask;
}
public interface ITicketRelationshipPolicy { bool IsAllowed(TicketType source,TicketType target,string relationType); }
